"""midlc crate layout: one generated file per interface and per shared module.

Part of the Messenger IDL compiler; see `midlc.py` for the CLI and
`docs/client-api-plan.md` 3.6. `--out libs/generated/src/lib.rs` writes that
file and, beside it, `errors.rs`, `topics.rs`, `objects.rs`, `rings.rs`,
`services.rs`, `declared.rs` and one `<interface module>.rs` per interface,
each gated behind a cargo feature of the same name (minus `os_lazy_`), so a
program compiles only the interfaces it names. `default = ["all"]` keeps every
dependent building everything until it opts out. The `[features]` block of
the crate's `Cargo.toml` is rewritten between its two markers.

The shared emitters produce inline `pub mod name { ... }` text (the
conformance corpus compiles those inline); this module turns each into the
body of a file.
"""

from __future__ import annotations

import re
from pathlib import Path

from midlc_model import Interface, MidlError

REGEN = "python tools/midlc/midlc.py --out libs/generated/src/lib.rs idl/*.midl"
FILE_HEADER = f"// @generated by tools/midlc/midlc.py - do not edit.\n// Regenerate with:\n//   {REGEN}\n"
MARKER_BEGIN = "# @generated features begin (tools/midlc/midlc.py, do not edit)"
MARKER_END = "# @generated features end"
MOD_LINE = re.compile(r"^pub mod (\w+) \{$")


def split_module(text: str) -> tuple[str, list[str], list[str]]:
    """`(name, lines before the module, body)` of an inline `pub mod name { }`:
    the leading doc/attribute lines stay on the `mod` declaration in `lib.rs`,
    the body is dedented to be a file."""
    lines = text.rstrip("\n").split("\n")
    start = next(i for i, line in enumerate(lines) if MOD_LINE.match(line))
    if lines[-1] != "}":
        raise MidlError(f"generated module {MOD_LINE.match(lines[start]).group(1)} does not end in '}}'")
    body = []
    for line in lines[start + 1 : -1]:
        if line and not line.startswith("    "):
            raise MidlError(f"generated line is not indented inside its module: {line!r}")
        body.append(line[4:])
    return MOD_LINE.match(lines[start]).group(1), lines[:start], body


def feature_name(interface: Interface) -> str:
    """`os.lazy.confd.v1` -> `confd_v1`."""
    return re.sub(r"^os_lazy_", "", interface.module)


def check_features(interfaces: list[Interface]) -> None:
    seen: dict[str, str] = {}
    for interface in interfaces:
        name = feature_name(interface)
        if name in seen:
            raise MidlError(f"interfaces {seen[name]!r} and {interface.name!r} both map to the feature {name!r}")
        if name in ("all", "default"):
            raise MidlError(f"interface {interface.name!r} maps to the reserved feature name {name!r}")
        seen[name] = interface.name


def module_file(body: list[str]) -> str:
    return FILE_HEADER + "\n" + "\n".join(body) + "\n"


def mod_declaration(prefix: list[str], name: str, feature: str | None = None) -> list[str]:
    lines = list(prefix)
    if feature:
        lines.insert(0, f'#[cfg(feature = "{feature}")]')
    return lines + [f"pub mod {name};", ""]


def features_block(interfaces: list[Interface]) -> str:
    names = [feature_name(i) for i in interfaces]
    lines = [MARKER_BEGIN, 'default = ["all"]', "# Every interface; a program that wants fewer turns off default features and names its own."]
    lines.append("all = [" + ", ".join(f'"{n}"' for n in names) + "]")
    lines += [f"{n} = []" for n in names]
    lines.append(MARKER_END)
    return "\n".join(lines) + "\n"


def rewrite_features(cargo_toml: str, interfaces: list[Interface]) -> str | None:
    """`cargo_toml` with its generated feature block replaced, or None when it
    has no markers (a crate that does not use the split layout)."""
    begin, end = cargo_toml.find(MARKER_BEGIN), cargo_toml.find(MARKER_END)
    if begin < 0 or end < begin:
        return None
    end += len(MARKER_END) + 1
    return cargo_toml[:begin] + features_block(interfaces) + cargo_toml[end:]


def stale_generated(directory: Path, files: dict[str, str]) -> list[str]:
    """`.rs` files of `directory` that midlc wrote earlier and no longer does."""
    if not directory.is_dir():
        return []
    return sorted(
        p.name
        for p in directory.glob("*.rs")
        if p.name not in files and "@generated by tools/midlc/midlc.py" in p.read_text(encoding="utf-8")[:200]
    )
